{
  "name": "fixture_replay",
  "description": "Verify fixture hashes and load its databases on the configured scratch Postgres, check real constraints, then drop all throwaway databases. No writes to configured environment databases. Kafka files are for the service test producer. For actual tests use test_run fixture_path.",
  "group": "code",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "workspace": {
        "type": "string",
        "description": "Workspace id"
      },
      "directory": {
        "type": "string",
        "description": "Fixture resource directory"
      },
      "allow_incomplete": {
        "type": "boolean",
        "default": false,
        "description": "Replay despite reported capture gaps"
      }
    },
    "required": [
      "workspace",
      "directory"
    ]
  }
}
